def _eligible(fact: dict[str, Any], session_dates: dict[str, str], cutoff: str,
              excluded_sessions: set[str]) -> bool:
    cutoff_at = _parse_time(cutoff, "temporal cutoff")
    session_ids = _provenance_session_ids(fact)
    if not session_ids:
        return False
