func privacyRegressionCommandFixture(t *testing.T, now time.Time) (Options, string) {
	t.Helper()
	repoDir := t.TempDir()
	runner := &fakeCommandRunner{responses: map[string]fakeCommandResponse{
		fakeCommandKey("git", "rev-parse", "--show-toplevel"): {stdout: repoDir + "\n"},
		fakeCommandKey("git", "remote", "get-url", "origin"):  {stdout: "git@github.com:acme/privacy-regression.git\n"},
		fakeCommandKey("git", "branch", "--show-current"):     {stdout: "main\n"},
	}}
	opts := Options{
		Version: "test",
		Env: EntireEnv{
			RepoRoot:       repoDir,
			PluginDataDir:  t.TempDir(),
			PluginCacheDir: t.TempDir(),
		},
		Runner: runner,
		Now:    func() time.Time { return now },
	}
	storage, err := repoStoragePaths(context.Background(), runner, opts.Env, repoDir)
	if err != nil {
		t.Fatal(err)
	}
	fixture := writePrivacyFixture(t)
	if err := os.MkdirAll(filepath.Dir(storage.BrainDir), 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.Rename(fixture, storage.BrainDir); err != nil {
		t.Fatal(err)
	}
	return opts, storage.BrainDir
}

func writePrivacyVectorFixture(t *testing.T, statements ...string) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), "vectors.sqlite")
	db, err := sql.Open(sqliteDriverName, path)
	if err != nil {
		t.Fatal(err)
	}
	for _, statement := range statements {
		if _, err := db.Exec(statement); err != nil {
			_ = db.Close()
			t.Fatalf("execute %q: %v", statement, err)
		}
	}
	if err := db.Close(); err != nil {
		t.Fatal(err)
	}
	return path
}

func TestPrivacyVectorSnapshotInspectsRealSQLiteMembership(t *testing.T) {
	path := writePrivacyVectorFixture(t,
		`CREATE TABLE history_ids(rowid INTEGER PRIMARY KEY, record_id TEXT UNIQUE NOT NULL)`,
		`INSERT INTO history_ids(record_id) VALUES ('retained'), ('excluded')`,
	)
	findings, err := inspectPrivacyVectorIDsSnapshot(path, "history/embed/vectors.sqlite", map[string]struct{}{"retained": {}}, "secret-sess")
	if err != nil {
		t.Fatal(err)
	}
	if len(findings) != 1 || findings[0].SessionID != "secret-sess" || findings[0].Artifact != "vector_store" || !strings.Contains(findings[0].Detail, "excluded") {
		t.Fatalf("findings = %+v, want the excluded real SQLite record only", findings)
	}

	findings, err = inspectPrivacyVectorIDsSnapshot(path, "history/embed/vectors.sqlite", map[string]struct{}{"retained": {}, "excluded": {}}, "secret-sess")
	if err != nil || len(findings) != 0 {
		t.Fatalf("all retained: findings=%+v err=%v", findings, err)
	}
}

// yields an empty slice so first-run callers do not special-case it. Blank
// lines are skipped; a malformed line is a hard error so a corrupt store is
// surfaced rather than silently dropping records.
func loadFacts(brainDir, branch string) ([]factRecord, error) {
	rel := factsFileRelPath(branch)
	if err := rejectExistingSymlinkPathComponents(brainDir, rel); err != nil {
		return nil, err
	}
	path := filepath.Join(brainDir, filepath.FromSlash(rel))
	if info, err := os.Lstat(path); err == nil && !info.Mode().IsRegular() {
		return nil, fmt.Errorf("fact store is not a regular file: %s", rel)
	}
	records, err := parseFactsFile(path)
	if err != nil {
		// The bare parse error names the damage but not the repair, and this
		// is the error every read surface shows a user. Name the repair here,
		// once, the way the history index names `refresh history`.
		// parseFactsFile itself stays clean so the integrity report (which
		// quotes it inside a fuller sentence) does not say it twice.
		return nil, fmt.Errorf("%w; %s", err, factsRepairHint)
	}
	return records, nil

}

// parseFactsFile reads a facts.ndjson file at an absolute path. A missing file
// yields an empty slice; a malformed line is a hard error so a corrupt store is
// surfaced rather than silently dropping records. The byte-level scan lives in
// factmerge.ParseNDJSON; this keeps only the file/path handling and restores the
// historical "parse <file> line N: ..." message the core cannot know the path
// for.
func semanticAuditSnapshotCoverage(brainDir string, source *semanticSourceManifest, freshness staleReport) (semanticAuditCoverage, error) {
	if source == nil || strings.TrimSpace(source.SnapshotPath) == "" {
		return semanticAuditCoverage{}, nil
	}
	if axis, ok := freshness.Axes["snapshot"]; ok && axis.State != "ok" {
		return semanticAuditCoverage{}, nil
	}
	snapshotRel, err := validateSemanticSnapshotPath(source.SnapshotPath)
	if err != nil {
		return semanticAuditCoverage{}, err
	}
	if err := rejectSymlinkPathComponents(brainDir, snapshotRel); err != nil {
		return semanticAuditCoverage{}, err
	}
	f, err := os.Open(filepath.Join(brainDir, snapshotRel))
	if err != nil {
		return semanticAuditCoverage{}, fmt.Errorf("open semantic snapshot for audit: %w", err)
	}
	defer f.Close()
	files := map[string]string{}
	languages := map[string]int{}
	kinds := map[string]int{}
	relationTypes := map[string]int{}
	scanner := newSemanticScanner(f)
	line := 0
	for scanner.Scan() {
		line++
		if line == 1 {
			continue
		}
		var record semanticRecord
		if err := json.Unmarshal(scanner.Bytes(), &record); err != nil {
			return semanticAuditCoverage{}, fmt.Errorf("parse semantic snapshot line %d: %w", line, err)
		}
		switch record.RecordType {
		case "file":
			if path := record.semanticPath(); path != "" {
				files[path] = auditCoverageName(record.Language)
			}
		case "symbol":
			languages[auditCoverageName(record.Language)]++
			kinds[auditCoverageName(record.Kind)]++
			if path := record.semanticPath(); path != "" {
				if files[path] == "" || files[path] == "unknown" {
					files[path] = auditCoverageName(record.Language)
				}
			}
		case "relation":
			relationTypes[auditCoverageName(record.Type)]++
		}
	}
	if err := scanner.Err(); err != nil {
		return semanticAuditCoverage{}, fmt.Errorf("scan semantic snapshot for audit: %w", err)
	}
	fileLanguages := map[string]int{}
	for _, language := range files {
		fileLanguages[auditCoverageName(language)]++
	}
	return semanticAuditCoverage{
		FileLanguages: semanticAuditCountsFromMap(fileLanguages),
		Languages:     semanticAuditCountsFromMap(languages),
		SymbolKinds:   semanticAuditCountsFromMap(kinds),
		RelationTypes: semanticAuditCountsFromMap(relationTypes),
	}, nil
}

func auditCoverageName(value string) string {
	value = strings.TrimSpace(value)
	if value == "" {
		return "unknown"
	}
	return value
}

func semanticAuditCountsFromMap(counts map[string]int) []semanticAuditCount {
