 if err:=json.Unmarshal([]byte(out),&result);err!=nil {t.Fatal(err)}
 if result.Branch!="main" || result.Applied!=applied || result.Pruned!=pruned || result.Orphans!=orphans || result.Remaining!=remaining {t.Fatalf("unexpected GC summary: %+v",result)}
}

