func runSessionsPurge(ctx context.Context, cmd *cobra.Command, opts Options, sessionID string, dryRun, jsonOut bool) error {
	sessionID = strings.TrimSpace(sessionID)
	if sessionID == "" {
		return fmt.Errorf("session id is required")
	}
	storage, err := resolveSessionsBrain(ctx, opts)
	if err != nil {
		return err
	}
	brainDir := storage.BrainDir
	var plan sessionPurgePlan
	apply := func() error {
		return withBrainWriteLock(brainDir, func() error {
			var planErr error
			plan, planErr = buildSessionPurgePlan(brainDir, sessionID)
			if planErr != nil {
				return planErr
			}
			plan.Caveats = append(plan.Caveats, purgeGitmetaSyncCaveats(opts.Env, storage.Key, plan)...)
			plan.DryRun = dryRun
			if dryRun {
				return nil
			}
			return executeSessionPurge(brainDir, sessionID, plan, opts.Now().UTC())
		})
	}
	if !dryRun {
		operation := apply
		apply = func() error { return withBrainPrivacySideEffectLock(brainDir, operation) }
	}
	if err := apply(); err != nil {
		return err
	}
	if jsonOut {
		return writeJSON(cmd, plan)
	}
	return writeText(cmd, func(out io.Writer) {
		mode := "purged"
		if plan.DryRun {
			mode = "purge (dry-run) would remove"
		}
		fmt.Fprintf(out, "%s session %s:\n", mode, plan.SessionID)
		for _, artifact := range plan.Transcripts {
			fmt.Fprintf(out, "  transcript %s (%d bytes)\n", artifact.Path, artifact.Bytes)
		}
		fmt.Fprintf(out, "  %d derived index records\n", plan.Records)
		if plan.FactsDeleted > 0 || plan.FactAnchorsStripped > 0 {
			fmt.Fprintf(out, "  %d single-source facts deleted, %d anchors stripped from corroborated facts\n", plan.FactsDeleted, plan.FactAnchorsStripped)
		}
		if plan.Episodes > 0 {
			fmt.Fprintf(out, "  %d pattern episodes\n", plan.Episodes)
		}
		for _, artifact := range plan.DerivedStores {
			fmt.Fprintf(out, "  derived store %s (%d bytes, rebuilds from surviving truth)\n", artifact.Path, artifact.Bytes)
		}
		for _, artifact := range plan.WorkMetadata {
			fmt.Fprintf(out, "  memory work metadata %s (%d bytes)\n", artifact.Path, artifact.Bytes)
		}
		for _, caveat := range plan.Caveats {
			fmt.Fprintf(out, "  NOT purged: %s\n", caveat)
		}
	})
}

// buildSessionPurgePlan computes exactly what a purge touches, from the
// trusted manifest and the current index. Purging an unknown or already-purged
}

func TestSessionPurgeCanaryAbsentEverywhereAndIdempotent(t *testing.T) {
	brainDir := writePrivacyFixture(t)
	now := time.Date(2026, 8, 7, 13, 0, 0, 0, time.UTC)

	// Warm the FTS index so purge has a derived store to remove.
	manifest, _ := loadBrainManifest(brainDir)
	index, err := loadBrainHistoryIndex(brainDir, manifest.Sources.History)
	if err != nil {
		t.Fatal(err)
	}
	if _, ok := rankHistoryViaFTS(brainDir, index, "history", "rotated", 5); !ok {
		t.Fatal("fts warmup failed")
	}

	// Dry-run predicts the artifacts and changes nothing.
	plan, err := buildSessionPurgePlan(brainDir, "secret-sess")
	if err != nil {
		t.Fatal(err)
	}
	if len(plan.Transcripts) != 1 || plan.Transcripts[0].Path != "sessions/main/20260802T000000Z_secret.jsonl" || plan.Transcripts[0].Bytes == 0 {
		t.Fatalf("plan transcripts = %+v", plan.Transcripts)
	}
	if plan.Records == 0 {
		t.Fatal("plan must count derived records")
	}
	hasFTS := false
	for _, store := range plan.DerivedStores {
		if store.Path == historyFTSDBRelPath() {
			hasFTS = true
		}
	}
	if !hasFTS {
		t.Fatalf("plan missing the FTS store: %+v", plan.DerivedStores)
	}
	if _, err := os.Stat(filepath.Join(brainDir, "sessions", "main", "20260802T000000Z_secret.jsonl")); err != nil {
		t.Fatalf("dry-run computation must not delete anything: %v", err)
	}

	// Execute the purge.
	if err := executeSessionPurge(brainDir, "secret-sess", plan, now); err != nil {
		t.Fatal(err)
	}
	assertCanaryAbsent(t, brainDir)
	stones := loadSessionTombstones(brainDir)
	if _, ok := stones.Excluded["secret-sess"]; !ok {
		t.Fatal("purge must leave a tombstone")
	}
	// The clean session survives untouched.
	manifest, _ = loadBrainManifest(brainDir)
	if manifest.Sources.History.Exchanges != 1 {
		t.Fatalf("surviving exchanges = %d, want 1 (clean session only)", manifest.Sources.History.Exchanges)
	}

	// Idempotent: purging again is an empty plan and succeeds.
	again, err := buildSessionPurgePlan(brainDir, "secret-sess")
	if err != nil {
		t.Fatal(err)
	}
