package cli

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// These use the public root command with a durable episode fixture. They pin
// the packet users receive, rather than the ranking helpers that build it.
func TestBriefOutputRootJSONAndTextContracts(t *testing.T) {
	opts, repoDir, _ := commandRegressionFixture(t)
	for _, rel := range []string{"providers/responses.go", "client/previous_response.go"} {
		path := filepath.Join(repoDir, rel)
		if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, []byte("package client\n// metadata previous_response_id\n"), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	task := "repair Responses API metadata and previous_response_id contract"
	out, err := execute(t, NewRootCommand(opts), "brief", task, "--json", "--limit", "8")
	if err != nil {
		t.Fatalf("brief json: %v\n%s", err, out)
	}
	var report map[string]any
	if err := json.Unmarshal([]byte(out), &report); err != nil {
		t.Fatalf("decode: %v\n%s", err, out)
	}
	if report["task"] != task || report["status"] == nil || report["guidance"] == nil {
		t.Fatalf("public report missing task/status/guidance: %#v", report)
	}
	files, _ := report["likely_edit_files"].([]any)
	joined := ""
	for _, file := range files {
		joined += "\n" + file.(string)
	}
	for _, want := range []string{"providers/responses.go", "client/previous_response.go"} {
		if !strings.Contains(joined, want) {
			t.Fatalf("brief metadata/previous-response routing omitted %q: %s", want, joined)
		}
	}
	if strings.Contains(out, "private metadata") {
		t.Fatalf("brief leaked fixture-private text: %s", out)
	}
	text, err := execute(t, NewRootCommand(opts), "brief", task, "--limit", "8")
	if err != nil || !strings.Contains(text, "task:") || !strings.Contains(text, task) {
		t.Fatalf("brief text: %v\n%s", err, text)
	}
}

func TestBriefOutputRejectsInvalidBudgetAtRoot(t *testing.T) {
	opts, _, _ := commandRegressionFixture(t)
	out, err := execute(t, NewRootCommand(opts), "brief", "metadata", "--limit", "0", "--json")
	if err == nil || !strings.Contains(err.Error(), "--limit must be greater than zero") {
		t.Fatalf("invalid budget: %v\n%s", err, out)
	}
}
func TestMemoryLifecycleDefensiveHelpersAndCorruptInputs(t *testing.T) {
	if got := memoryStatusScalar(make(chan int)); got != "null" {
		t.Fatalf("unencodable scalar=%q", got)
	}
	if now := memoryClockNow(nil); now.Location() != time.UTC || time.Since(now) > time.Minute {
		t.Fatalf("nil clock=%v", now)
	}
	t.Setenv("ENTIRE_BRAIN_EMBEDDER", "")
	if pending, err := syncMemoryProjectionVectors(context.Background(), t.TempDir(), time.Now().UTC()); err != nil || pending {
		t.Fatalf("unset vector sync pending=%t err=%v", pending, err)
	}

	brainDir := t.TempDir()
	if err := os.WriteFile(filepath.Join(brainDir, exportManifestFileName), []byte("{"), 0o600); err != nil {
		t.Fatal(err)
	}
	if _, err := reconcileMemoryJobsLockedDetailed(brainDir, "corrupt", time.Now().UTC(), nil, false, nil); err == nil {
		t.Fatal("corrupt reconcile manifest unexpectedly succeeded")
	}
	if _, err := maintainMemoryWorkerStateLocked(brainDir, time.Now().UTC(), nil); err == nil {
		t.Fatal("corrupt maintenance manifest unexpectedly succeeded")
	}
	if _, err := runMemoryProjectionLane(context.Background(), brainDir, time.Now().UTC(), "corrupt-owner"); err == nil {
		t.Fatal("corrupt projection manifest unexpectedly succeeded")
	}
	if _, err := runMemoryAbstractLane(context.Background(), t.TempDir(), brainDir, time.Now().UTC(), "corrupt-owner"); err == nil {
		t.Fatal("corrupt abstract manifest unexpectedly succeeded")
	}
}

func TestMemoryLifecycleJobsTextIncludesErrorsIssuesAndFilters(t *testing.T) {
	opts, brainDir := memoryAdminCommandFixture(t)
	now := opts.Now().UTC()
	manifest, err := loadBrainManifest(brainDir)
	if err != nil {
		t.Fatal(err)
	}
	digest := "sha256:" + strings.Repeat("a", 64)
	sessionRef, ok := conversationSessionRef(manifest.RepoKey, "main", "session-a", digest)
	if !ok {
		t.Fatal("failed to construct canonical session ref")
	}
	job := memoryJob{
		SchemaVersion: memoryJobSchemaVersion, Kind: memoryJobKindProjection,
		RepoKey: manifest.RepoKey, SessionID: "session-a", SessionRef: sessionRef,
		Branch: "main", InputDigest: digest, Trigger: "regression", State: memoryJobStatePending,
		CreatedAt: now, AvailableAt: now,
	}
	job.JobID = memoryJobID(job.RepoKey, job.SessionRef, job.InputDigest, job.Kind)
	if err := saveMemoryJob(brainDir, job); err != nil {
		t.Fatal(err)
	}
	running, err := transitionMemoryJob(brainDir, job, memoryJobStateRunning, now, "")
	if err != nil {
		t.Fatal(err)
	}
	job, err = transitionMemoryJob(brainDir, running, memoryJobStateRetryable, now, "memory_source_stale")
	if err != nil {

