// reduces latency and correctness never depends on it firing. The incremental
// cache makes re-firing for the same session free.
//
// Unlike pre-edit/post-failure this verb may legitimately take minutes and
// spend tokens — the session is over, nobody is waiting — but it keeps the
// rest of the hook contract: stdout stays empty (a one-line summary goes to
// stderr), and environment problems (no repo, no brain, no agent on PATH)
// are silence, never an error.
func newHookSessionEndCommand(opts Options) *cobra.Command {
	var (
		sessionID string
		branch    string
		agent     string
		model     string
		effort    string
	)
	cmd := &cobra.Command{
		Use:   "session-end --session <id>",
		Short: "Refresh and distill the just-ended session (spends tokens; silent on env problems)",
		Args:  cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			if strings.TrimSpace(sessionID) == "" {
				return fmt.Errorf("--session <id> is required")
			}
			if memoryWorkerOrigin() {
				return nil
			}
			target := agentSurfaceTarget(opts, nil)
			repoDir, local, err := resolveLocalTargetRepoDir(cmd.Context(), opts.Runner, target)
			if err != nil || !local {
				return nil // no local repo: silence, never an error
			}
			perRepo := opts
			perRepo.Env.RepoRoot = repoDir
			// Export only changed sessions and publish the short-term overlay so
			// recall and distill can see the just-ended session immediately. The
			// durable coordinator performs the heavier long-term consolidation.
			sub := &cobra.Command{}
			sub.SetContext(cmd.Context())
			sub.SetOut(cmd.ErrOrStderr())
			sub.SetErr(cmd.ErrOrStderr())
			_, deltaErr := watchShortTermDelta(cmd.Context(), sub, perRepo, repoDir)

			// Record the lifecycle event even when export failed. The hint is
			// content-free and durable; startup/watch reconciliation or a later
			// worker pass can repair the missed export without retaining content.
			storage, storageErr := repoStoragePaths(cmd.Context(), perRepo.Runner, perRepo.Env, repoDir)
			if storageErr == nil {
				resolvedBranch := strings.TrimSpace(branch)
				if resolvedBranch == "" {
					if current, gitErr := gitScalar(cmd.Context(), perRepo.Runner, repoDir, "branch", "--show-current"); gitErr == nil {
						resolvedBranch = strings.TrimSpace(current)
					}
				}
				_, warning, hintErr := recordMemoryLifecycleAndLaunch(
					storage.BrainDir, repoDir, storage.Key, sessionID, resolvedBranch, "session_end", perRepo.Now().UTC(),
				)
				if hintErr != nil {
					fmt.Fprintf(cmd.ErrOrStderr(), "session-end: memory hint failed: %v\n", hintErr)
				} else if warning != "" {
					fmt.Fprintf(cmd.ErrOrStderr(), "session-end: %s\n", warning)
				}
			}
			// Deterministic, token-free and bounded: index the commits the
			// session just produced so "which checkpoint changed this symbol"
			// is answerable immediately. It runs AFTER the durable lifecycle
			// hint (that must never wait on a slow provider) and independently
			// of the export result, since it reads git, not transcripts. Never
			// fails the hook.
			if entityErr := refreshEntityIndexQuietly(cmd.Context(), perRepo, repoDir); entityErr != nil {
				fmt.Fprintf(cmd.ErrOrStderr(), "session-end: entity index refresh skipped: %v\n", entityErr)
			}
			if deltaErr != nil {
				fmt.Fprintf(cmd.ErrOrStderr(), "session-end: incremental export failed: %v\n", deltaErr)
				return nil
			}
			distillOpts := distillCommandOptions{
				session:             sessionID,
				agent:               agent,
				model:               model,
				effort:              effort,
				timeout:             defaultDistillTimeout,
				maxChunkBytes:       defaultDistillChunkSize,
				confidenceThreshold: defaultFactConfidenceThreshold,
				// Constructed in Go, so the flag defaults never applied: without
				// this the hook's distill was rejected outright by runDistill's
				// concurrency guard, and the "closing the write loop" step
				// silently never ran.
				concurrency: defaultDistillConcurrency,
			}
			if err := runDistill(cmd.Context(), sub, opts, distillOpts, repoDir); err != nil {
				// No agent on PATH, session not exported yet, etc.: report on
				// stderr for the curious, succeed for the harness.
				fmt.Fprintf(cmd.ErrOrStderr(), "session-end: distill skipped: %v\n", err)
			}
			return nil
		},
	}
	cmd.Flags().StringVar(&sessionID, "session", "", "The just-ended session's id")
	cmd.Flags().StringVar(&branch, "branch", "", "Captured branch when the host knows it")
	cmd.Flags().StringVar(&agent, "agent", "auto", "Distill agent: auto, codex, claude-code, or command")
	cmd.Flags().StringVar(&model, "model", "", "Cheap/fast model override for the distill agent (recommended)")
	cmd.Flags().StringVar(&effort, "effort", "", "Reasoning-effort override (e.g. low) — pairs with --model for a cheap run")
	return cmd
}

package cli

import (
	"strings"
	"testing"
	"time"
)

func hookTestFacts(now time.Time) []factRecord {
	return []factRecord{
		{ID: "f:neg", Kind: factKindClosedNegative, Paths: []string{"architecture.data.flow"},
			Text: "Relaxing the history term-coverage gate to 2-of-N was tried and failed: it admitted filler-word noise; BM25 is the fix.", Status: factStatusActive, UpdatedAt: now},
		{ID: "f:gotcha", Kind: factKindGotcha, Paths: []string{"constraints.invariants.general"},
			Text: "The distill cache fails silently when the facts directory is read-only; flushes retry on the next interval.", Status: factStatusActive, UpdatedAt: now},
		{ID: "f:conv", Kind: factKindConvention, Paths: []string{"workflow.testing.rules"},
			Text: "The history term-coverage gate is reviewed during retrieval syncs.", Status: factStatusActive, UpdatedAt: now},
		{ID: "f:file", Kind: factKindDecision, Paths: []string{"architecture.boundaries.rationale"},
			Text: "`history_fts.go` keeps the BM25 relevance cutoff relative to the top score, not absolute.", Status: factStatusActive, UpdatedAt: now},
	}
}

func TestHookMatchFailureKindsAndThreshold(t *testing.T) {
	now := time.Date(2026, 6, 10, 12, 0, 0, 0, time.UTC)
	facts := hookTestFacts(now)

	// A failure mentioning the coverage gate matches the closed-negative but
	// must NOT surface the equally-matching convention (wrong kind for a
	// failure moment).
	hits := hookMatchFailure(facts, "test failed: history term-coverage gate admitted weak matches")
	if len(hits) == 0 || hits[0].ID != "f:neg" {
		t.Fatalf("expected the closed-negative to match the failure, got %+v", hits)
	}
	for _, h := range hits {
		if h.ID == "f:conv" {
			t.Fatalf("convention kind must not surface on a failure: %+v", hits)
		}
	}

	// An unrelated failure stays silent — the precision bar holds.
	if hits := hookMatchFailure(facts, "compile error: undefined variable in renderer"); len(hits) != 0 {
		t.Fatalf("unrelated failure should match nothing, got %+v", hits)
	}
}

func TestHookPreEditLocusMatch(t *testing.T) {
	now := time.Date(2026, 6, 10, 12, 0, 0, 0, time.UTC)
	facts := hookTestFacts(now)
	// The pre-edit path: file + stem against fact locus (backticked file name).
	hits := factsRelevantToChange([]string{"internal/cli/history_fts.go", "history_fts"}, nil, facts, 8)
	if len(hits) != 1 || hits[0].ID != "f:file" {
		t.Fatalf("expected the file-anchored fact for history_fts.go, got %+v", hits)
	}
	if hits := factsRelevantToChange([]string{"internal/cli/seed.go", "seed"}, nil, facts, 8); len(hits) != 0 {
		t.Fatalf("unrelated file should surface nothing, got %+v", hits)
	}
}

func TestHookEmitSilentAndBudget(t *testing.T) {
	now := time.Date(2026, 6, 10, 12, 0, 0, 0, time.UTC)
	cmd := newHookCommand(Options{})

	// Empty hits: complete silence (the contract; even a "no facts" line is noise).
	out, err := execute(t, cmd, "post-failure")
	if err != nil || strings.TrimSpace(out) != "" {
		t.Fatalf("empty stdin should be silent, got %q (err %v)", out, err)
	}

	// Budget caps a multi-fact emission but always emits at least one.
	long := strings.Repeat("a very long fact sentence ", 20)
	hits := []factRecord{
		{ID: "1", Kind: factKindGotcha, Text: long, Status: factStatusActive, UpdatedAt: now},
		{ID: "2", Kind: factKindGotcha, Text: long, Status: factStatusActive, UpdatedAt: now},
		{ID: "3", Kind: factKindGotcha, Text: long, Status: factStatusActive, UpdatedAt: now},
	}
	c := newHookPostFailureCommand(Options{})
	var sb strings.Builder
	c.SetOut(&sb)
	kept, err := hookEmit(c, hits, 150, false)
	if err != nil {
		t.Fatal(err)
	}
	if len(kept) == 0 || len(kept) >= 3 {
		t.Fatalf("hookEmit should report the capped emission it made, got %d facts", len(kept))
	}
	lines := strings.Split(strings.TrimSpace(sb.String()), "\n")
	if len(lines) >= 3 {
		t.Fatalf("budget 150 should cap the emission below 3 long facts, got %d lines", len(lines))
	}
	if len(lines) < 1 || !strings.HasPrefix(lines[0], "[gotcha]") {
		t.Fatalf("at least one fact must be emitted with a kind prefix, got %q", sb.String())
	}
}

// TestHookNeverFailsOutsideARepo locks in the harness-safety contract: in a
// directory with no repo and no brain, both hooks exit 0 with no output —
// a hook must never break the harness it is wired into.
func TestHookNeverFailsOutsideARepo(t *testing.T) {
	opts := Options{Env: EntireEnv{RepoRoot: t.TempDir()}, Runner: ExecRunner{}, Now: time.Now}
	out, err := execute(t, newHookCommand(opts), "pre-edit", "--file", "x.go")
	if err != nil || strings.TrimSpace(out) != "" {
		t.Fatalf("pre-edit outside a repo must be silent success, got %q (err %v)", out, err)
	}
	c := newHookCommand(opts)
	c.SetIn(strings.NewReader("some failure text"))
	out, err = execute(t, c, "post-failure", "--command", "go test")
	if err != nil || strings.TrimSpace(out) != "" {
		t.Fatalf("post-failure outside a repo must be silent success, got %q (err %v)", out, err)
	}

	// Flag misuse still errors (hand-testing stays debuggable).
	if _, err := execute(t, newHookCommand(opts), "pre-edit"); err == nil {
		t.Fatal("pre-edit without --file should error")
	}
}

