	if p.SessionsSinceDistill != 1 {
		t.Fatalf("expected 1 session since distill, got %d", p.SessionsSinceDistill)
	}
	if len(p.Branches) != 1 || p.Branches[0] != "main" {
		t.Fatalf("active branches = %v, want [main]", p.Branches)
	}
