package cli

import (
	"context"
	"encoding/json"
	"strings"
	"testing"
	"time"
)

func TestMCPDispatchRejectsMissingAndUnsupportedToolRequests(t *testing.T) {
	for _, tc := range []struct{ raw, want string }{
		{"null", "requires params with a tool name"},
		{`{}`, "requires params.name"},
		{`{"name":"not_a_tool","arguments":{}}`, "unknown tool: not_a_tool"},
		{`{"name":"brain_trace_path","arguments":{"from":"only"}}`, "to is required"},
	} {
		result, err := handleMCPToolCall(context.Background(), Options{}, json.RawMessage(tc.raw))
		if err == nil || result != nil {
			t.Fatalf("raw=%s result=%#v err=%v", tc.raw, result, err)
		}
		if !strings.Contains(err.Error(), tc.want) {
			t.Fatalf("error=%q want diagnostic %q", err, tc.want)
		}
	}
}

func TestMCPDispatchBrainStatusReturnsStructuredHealth(t *testing.T) {
	opts, _ := privacyRegressionCommandFixture(t, time.Date(2026, 9, 18, 0, 0, 0, 0, time.UTC))
	result, err := handleMCPToolCall(context.Background(), opts, json.RawMessage(`{"name":"brain_status","arguments":{"details":true}}`))
	if err != nil {
		t.Fatal(err)
	}
	content, ok := result["content"].([]map[string]any)
	if !ok || len(content) != 1 || content[0]["type"] != "text" {
		t.Fatalf("tool result=%#v", result)
	}
	text, _ := content[0]["text"].(string)
	if !strings.Contains(text, `"schema_version"`) || !strings.Contains(text, `"semantic"`) {
		t.Fatalf("status payload=%s", text)
	}
}
